        List<List<Integer>> result = new ArrayList<>();
        if (nums == null || nums.length == 0) {
            return result;
        }
        permuteHelper(nums, 0, nums.length - 1, result);
        return result;
    }

    private static void permuteHelper(int[] nums, int start, int end, List<List<Integer>> result) {
        if (start == end) {
            List<Integer> permutation = new ArrayList<>();
            for (int num : nums) {
                permutation.add(num);
            }
            result.add(permutation);
        } else {
            for (int i = start; i <= end; i++) {
                swap(nums, start, i);
                permuteHelper(nums, start + 1, end, result);
                swap(nums, start, i);
            }
        }
    }

    private static void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}
