private static void visitNeighbors(char[][] grid, int i, int j, boolean[][] visited) {
    visited[i][j] = true;
    if (i - 1 >= 0 && grid[i - 1][j] == '@' && !visited[i - 1][j]) {
        visitNeighbors(grid, i - 1, j, visited);
    }
    if (i + 1 < grid.length && grid[i + 1][j] == '@' && !visited[i + 1][j]) {
        visitNeighbors(grid, i + 1, j, visited);
    }
    if (j - 1 >= 0 && grid[i][j - 1] == '@' && !visited[i][j - 1]) {
        visitNeighbors(grid, i, j - 1, visited);
    }
    if (j + 1 < grid[0].length && grid[i][j + 1] == '@' && !visited[i][j + 1]) {
        visitNeighbors(grid, i, j + 1, visited);
    }
}
