    /* Check if the cell to the north, south, east, and west contain oil pockets */
    int north = (row > 0 && grid[row - 1][col] == '@') ? 1 : 0;
    int south = (row < grid.length - 1 && grid[row + 1][col] == '@') ? 1 : 0;
    int east = (col < grid[row].length - 1 && grid[row][col + 1] == '@') ? 1 : 0;
    int west = (col > 0 && grid[row][col - 1] == '@') ? 1 : 0;

    /* Return the oil deposit string */
    return "@" + row + "_" + col + "_" + north + "_" + south + "_" + east + "_" + west;
}
