    // Validate input
    if (date == null || !date.matches("\\d+ [a-zA-Z]{3} \\d{4}")) {
        throw new IllegalArgumentException("Invalid date format");
    }

    // Extract day, month, and year from input string
    String[] dateParts = date.split(" ");
    int d = Integer.parseInt(dateParts[0]);
    int m = Integer.parseInt(dateParts[1].substring(0, 3));
    int y = Integer.parseInt(dateParts[2]);

