public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Create a visited array to keep track of which nodes have been visited
    boolean[] visited = new boolean[n];
    // Set the initial node as visited
    visited[0] = true;
    // Create a queue to hold the nodes to visit
    LinkedList<Integer> queue = new LinkedList<>();
    // Enqueue the initial node
    queue.offer(0);
    // Initialize the minimum time as 0
    int minTime = 0;

    while (!queue.isEmpty()) {
        // Dequeue the current node
        int node = queue.poll();
        // If the current node has an apple, add the time required to collect it to the minimum time
        if (hasApple[node]) {
            minTime += 2;
        }
        // Mark the current node as visited
        visited[node] = true;
        // Iterate through the neighbors of the current node
        for (int neighbor : edges[node]) {
            // If the neighbor has not been visited yet, enqueue it
            if (!visited[neighbor]) {
                queue.offer(neighbor);
                // Mark the neighbor as visited
                visited[neighbor] = true;
            }
        }
    }
    return minTime;
}
