private List<String> recursizeMethod(String s, String substr) {
    // Base case: If the input string is empty, return an empty list.
    if (s.isEmpty()) {
        return new ArrayList<>();
    }

    // Recursive case: Split the input string into two parts:
    // the first character and the remaining characters.
    // If the first character is not already in the substring,
    // add it to the substring and append the result of the
    // recursive call to the list of unique substrings.
    char firstChar = s.charAt(0);
