private boolean canReconstruct(String substr, String s) {
    // Base case: If the substring is empty, return true.
    if (substr.isEmpty()) {
        return true;
    }

    // Recursive case: Check if the first character of the substring
    // can be found in the remaining substrings.
    // If it can be found, remove it from the remaining substrings
    // and recursively call the canReconstruct() method with the
    // remaining substrings.
    char firstChar = substr.charAt(0);
    if (s.contains(firstChar)) {
