private static void dfs(int[][] mat, int i, int j, boolean[][] visited) {
    if (i < 0 || i >= mat.length || j < 0 || j >= mat[0].length || mat[i][j] != 1 || visited[i][j]) {
        return;
    }

    visited[i][j] = true;
    currentLength++;

    dfs(mat, i - 1, j, visited); // up
    dfs(mat, i + 1, j, visited); // down
    dfs(mat, i, j - 1, visited); // left
    dfs(mat, i, j + 1, visited); // right
    dfs(mat, i - 1, j - 1, visited); // top-left
    dfs(mat, i + 1, j - 1, visited); // bottom-left
    dfs(mat, i - 1, j + 1, visited); // top-right
    dfs(mat, i + 1, j + 1, visited); // bottom-right
}
