private static int binarySearch(List<Integer> list, String target) {
    int low = 0;
    int high = list.size() - 1;
    while (low <= high) {
        int mid = (low + high) / 2;
        int compareResult = list.get(mid).toString().compareTo(target);
        if (compareResult == 0) {
            return mid;
        } else if (compareResult < 0) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -(low + 1);
}
