    int[] perfectSquares = new int[n + 1];
    perfectSquares[0] = 0;
    for (int i = 1; i <= n; i++) {
        perfectSquares[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            if (perfectSquares[i - j * j] != Integer.MAX_VALUE) {
                perfectSquares[i] = Math.min(perfectSquares[i], perfectSquares[i - j * j] + 1);
            }
        }
        if (perfectSquares[i] != Integer.MAX_VALUE) {
            minSquares = Math.min(minSquares, perfectSquares[i]);
        }
    }
    return minSquares == Integer.MAX_VALUE ? -1 : minSquares;
}
