public static String reverseWords(String s) {
  // Step 1: Split the input string into words
  String[] words = s.split(" ");

  // Step 2: Reverse the characters of each word
  for (int i = 0; i < words.length; i++) {
    char[] wordChars = words[i].toCharArray();
    for (int j = 0; j < wordChars.length / 2; j++) {
      char temp = wordChars[j];
      wordChars[j] = wordChars[wordChars.length - j - 1];
      wordChars[wordChars.length - j - 1] = temp;
    }
    words[i] = new String(wordChars);
  }

  // Step 3: Join the words back into a string
  return String.join(" ", words);
